        'kappa': kappa,
        'lambda_val': lambda_val,
        'mu': mu,
        'nu': nu,
        # Hidden construction parameters
        'c': c,
        'd': d,
        'e': e,
        's_num': s_num,
        's_den': s_den,
        'mode': mode
    }

